import{_ as l,a0 as u,w as n,s as o,I as t,x as s,a1 as p,A as e,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo","title":"如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22","tag":"202107","desc":""},"relativePath":"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo.md","filePath":"[post].md"}'),d={name:"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo.md"};function b(g,a,k,m,h,K){const i=u("Link");return n(),o("div",null,[a[21]||(a[21]=t("h1",{id:"如何在-kubuntu-21-04-中安裝和升級-kde-plasma-5-22",tabindex:"-1"},[s("如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22 "),t("a",{class:"header-anchor",href:"#如何在-kubuntu-21-04-中安裝和升級-kde-plasma-5-22","aria-label":"Permalink to “如何在 Kubuntu 21.04 中安裝和升級 KDE Plasma 5.22”"},"​")],-1)),a[22]||(a[22]=t("blockquote",null,[t("p",null,"KDE 團隊啓用了向後移植 PPA，你可以使用它在 Kubuntu 21.04 Hirsute Hippo 中安裝和升級到 KDE Plasma 5.22。")],-1)),a[23]||(a[23]=t("p",null,[t("img",{src:"https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Kubutu-21.04-running-with-KDE-Plasma-5.22-1024x531.jpg",alt:"Kubnutu 21.04 running with KDE Plasma 5.22"})],-1)),t("p",null,[a[1]||(a[1]=s("KDE 團隊最近發佈了 KDE Plasma 5.22，其中有相當多的增強功能、錯誤修復以及更新的 KDE 框架和應用版本。這個版本帶來了一些改進，如面板的自適應透明度，文件操作彈出時的用户友好通知，“發現”中的軟件包類型顯示，各種 Wayland 的變化等。在 ",-1)),p(i,{href:"https://www.debugpoint.com/2021/06/kde-plasma-5-22-release/"},{default:e(()=>[...a[0]||(a[0]=[s("這裏",-1)])]),_:1}),a[2]||(a[2]=s(" 查看更多關於功能細節。",-1))]),t("p",null,[a[4]||(a[4]=s("如果你正在運行 Kubuntu 21.04 Hirsute Hippo，或者在 ",-1)),p(i,{href:"https://www.debugpoint.com/2021/04/ubuntu-21-04-hirsute-hippo-release/"},{default:e(()=>[...a[3]||(a[3]=[s("Ubuntu 21.04 Hirsute Hippo",-1)])]),_:1}),a[5]||(a[5]=s(" 中安裝了自定義的 KDE Plasma，你可以通過以下步驟升級到最新版本。目前的 Hirsute Hippo 系列提供了先前版本 KDE Plasma 5.21.04 與 KDE Framework 5.80。",-1))]),a[24]||(a[24]=r(`<h3 id="在-kubuntu-21-04-hirsute-hippo-中安裝-kde-plasma-5-22-的步驟" tabindex="-1">在 Kubuntu 21.04 Hirsute Hippo 中安裝 KDE Plasma 5.22 的步驟 <a class="header-anchor" href="#在-kubuntu-21-04-hirsute-hippo-中安裝-kde-plasma-5-22-的步驟" aria-label="Permalink to “在 Kubuntu 21.04 Hirsute Hippo 中安裝 KDE Plasma 5.22 的步驟”">​</a></h3><p>按照下面的步驟進行。</p><p>如果你想使用圖形方法，那麼在“發現”中將 <code>ppa:kubuntu-ppa/backports</code> 添加到軟件源，然後點擊“更新”。</p><p>或者，使用下面的終端方法，以加快安裝速度。</p><ul><li><p><strong>步驟 1</strong>：打開一個終端，添加下面的 KDE Backports PPA。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div></li><li><p><strong>步驟 2</strong>：然後運行以下程序來啓動系統升級。這將在你的 Hirsute Hippo 系統中安裝最新的 KDE Plasma 5.22。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Upgrade-to-Plasma-5.22.jpg" alt="Upgrade to Plasma 5.22"></p></li><li><p><strong>步驟 3</strong>：更新後重新啓動，你應該會看到一個更新的 KDE Plasma 5.22 桌面。</p></li></ul><p>考慮到這是整個桌面環境的完整版本升級，安裝可能需要一些時間。</p><h3 id="在-ubuntu-21-04-中安裝-kde-plasma-5-22" tabindex="-1">在 Ubuntu 21.04 中安裝 KDE Plasma 5.22 <a class="header-anchor" href="#在-ubuntu-21-04-中安裝-kde-plasma-5-22" aria-label="Permalink to “在 Ubuntu 21.04 中安裝 KDE Plasma 5.22”">​</a></h3><p>如果你正在運行基於 GNOME 的默認 Ubuntu 21.04 Hirsute Hippo 桌面，你可以使用這個 PPA 來安裝最新的 KDE Plasma。下面是方法。</p><p>打開終端，添加 PPA（像上面的步驟那樣）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div><p>然後，刷新軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>然後運行下面的程序來安裝 Kubuntu 桌面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kubuntu-desktop</span></span></code></pre></div><p>這將在 Ubuntu 21.04 中與 GNOME 一起安裝 KDE Plasma 桌面。</p><h3 id="ubuntu-20-04-lts-中的-kde-plasma-5-22" tabindex="-1">Ubuntu 20.04 LTS 中的 KDE Plasma 5.22 <a class="header-anchor" href="#ubuntu-20-04-lts-中的-kde-plasma-5-22" aria-label="Permalink to “Ubuntu 20.04 LTS 中的 KDE Plasma 5.22”">​</a></h3><p>Ubuntu 20.04 LTS 版擁有早期的 KDE Plasma 5.18、KDE Framework 5.68、KDE Applications 19.12.3。所以，在它的整個生命週期中，它不會收到最新的 KDE 更新。所以，從技術上講，你可以添加上述 PPA 並安裝 KDE Plasma 5.22。但我不建議這樣做，因為不兼容的軟件包、框架可能會導致系統不穩定。</p><p>所以，建議你使用 Kubuntu 21.04 和上面的向後移植 PPA 或者使用 KDE neon 來體驗最新的 Plasma 桌面。</p><h3 id="卸載-kde-plasma-5-22" tabindex="-1">卸載 KDE Plasma 5.22 <a class="header-anchor" href="#卸載-kde-plasma-5-22" aria-label="Permalink to “卸載 KDE Plasma 5.22”">​</a></h3><p>如果你改變主意，想回到 KDE Plasma 的原始版本，那麼安裝 <code>ppa-purge</code> 並清除 PPA。這將使軟件包降級，並啓用倉庫版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>我希望這個快速指南能幫助你在 Kubuntu 21.04 Hirsute Hippo 中安裝最新的 KDE Plasma 5.22。這可以讓你體驗到最新的 KDE 技術以及 KDE 框架和應用。然而，你應該知道，並不是所有的功能都應該在向後移植 PPA 中提供，它只有選定的功能和錯誤修復，這才能通過迴歸測試並安全使用。也就是説，你總是可以把 KDE Neon 安裝成一個全新的系統來享受 KDE 的最新技術。</p><hr>`,24)),t("p",null,[a[7]||(a[7]=s("via: ",-1)),p(i,{href:"https://www.debugpoint.com/2021/06/plasma-5-22-kubuntu-21-04/"},{default:e(()=>[...a[6]||(a[6]=[s("https://www.debugpoint.com/2021/06/plasma-5-22-kubuntu-21-04/",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=s("作者：",-1)),p(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[8]||(a[8]=[s("Arindam",-1)])]),_:1}),a[13]||(a[13]=s(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 譯者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:e(()=>[...a[10]||(a[10]=[s("geekpi",-1)])]),_:1}),a[15]||(a[15]=s(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[18]||(a[18]=s("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...a[17]||(a[17]=[s("Linux中國",-1)])]),_:1}),a[20]||(a[20]=s(" 榮譽推出",-1))])])}const E=l(d,[["render",b]]);export{D as __pageData,E as default};
